contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(collectAmount <= depositAmount);
        require(address(this).balance >= depositAmount);

        // setup: MinSum = 0 so collection is allowed after one deposit
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        uint myEthBefore = address(this).balance;

        c.Collect(collectAmount); if (__ESBMC_reverted()) return;

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfter = address(c).balance;
        uint myEthAfter = address(this).balance;

        assert(balAfter == balBefore - collectAmount
            && myEthAfter == myEthBefore + collectAmount
            && ethAfter == ethBefore - collectAmount);
    }

    receive() external payable {}
}

